inputs.value:
function main({ agent_reply, case_id }) {
  const raw = String(agent_reply ?? "").trim();

  function extractJsonText(text) {
    const cleaned = text
      .replace(/^\s*```(?:json)?\s*/i, "")
      .replace(/\s*```\s*$/i, "")
      .trim();

    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");

    if (start < 0 || end <= start) return "";
    return cleaned.slice(start, end + 1);
  }

  function hashString(value) {
    let hash = 2166136261;

    for (let i = 0; i < value.length; i++) {
      hash ^= value.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }

    return hash >>> 0;
  }

  function remapOptionLetters(text, oldToNew) {
    if (typeof text !== "string" || !text) return text;

    const letters = ["A", "B", "C", "D"];

    function mapLetter(letter) {
      const oldIndex = letters.indexOf(letter);

      if (
        oldIndex < 0 ||
        !Number.isInteger(oldToNew[oldIndex])
      ) {
        return letter;
      }

      return letters[oldToNew[oldIndex]];
    }

    return text
      .replace(
        /选项([ABCD])/g,
        (_, letter) => `选项${mapLetter(letter)}`
      )
      .replace(
        /([ABCD])项/g,
        (_, letter) => `${mapLetter(letter)}项`
      );
  }

  const jsonText = extractJsonText(raw);

  if (!jsonText) {
    return {
      normalized_json: raw,
      normalization_status: "INVALID_JSON",
      normalization_report:
        "未找到可解析的JSON根对象；未修改原始输出。"
    };
  }

  let data;

  try {
    data = JSON.parse(jsonText);
  } catch (error) {
    return {
      normalized_json: raw,
      normalization_status: "INVALID_JSON",
      normalization_report:
        `JSON解析失败：${String(
          error?.message || error
        )}；未修改原始输出。`
    };
  }

  if (data?.generation_status !== "success") {
    return {
      normalized_json: JSON.stringify(data, null, 2),
      normalization_status: "PASSTHROUGH",
      normalization_report:
        "generation_status不是success，未修改题目。"
    };
  }

  if (
    !Array.isArray(data.questions) ||
    data.questions.length < 2 ||
    data.questions.length > 5
  ) {
    return {
      normalized_json: JSON.stringify(data, null, 2),
      normalization_status: "STRUCTURE_INVALID",
      normalization_report:
        "success状态下questions题量不在2至5题范围内；未修改题目。"
    };
  }

  const structuralProblems = [];

  for (let i = 0; i < data.questions.length; i++) {
    const question = data.questions[i];
    const label = question?.id || `Q${i + 1}`;

    if (
      !question ||
      !Array.isArray(question.options) ||
      question.options.length !== 4
    ) {
      structuralProblems.push(
        `${label}：options不是4项`
      );
      continue;
    }

    if (
      question.options.some(
        (option) =>
          typeof option !== "string" ||
          !option.trim()
      )
    ) {
      structuralProblems.push(
        `${label}：存在空选项或非字符串选项`
      );
    }

    if (new Set(question.options).size !== 4) {
      structuralProblems.push(
        `${label}：存在重复选项`
      );
    }

    if (
      !Number.isInteger(question.answer) ||
      question.answer < 0 ||
      question.answer > 3
    ) {
      structuralProblems.push(
        `${label}：answer不是0至3的整数`
      );
      continue;
    }

    if (
      question.answer_text !==
      question.options[question.answer]
    ) {
      structuralProblems.push(
        `${label}：answer_text与options[answer]不一致`
      );
    }
  }

  if (structuralProblems.length > 0) {
    return {
      normalized_json: JSON.stringify(data, null, 2),
      normalization_status: "STRUCTURE_INVALID",
      normalization_report:
        `${structuralProblems.join("；")}；` +
        "未猜测或修改医学答案。"
    };
  }

  const answerPatterns = [
    [0, 2, 1, 3, 0],
    [1, 3, 0, 2, 1],
    [2, 0, 3, 1, 2],
    [3, 1, 2, 0, 3],
    [0, 3, 1, 2, 3],
    [2, 1, 3, 0, 1]
  ];

  const seed = String(
    case_id ||
    data.case_summary ||
    "default-case"
  );

  const fullPattern =
    answerPatterns[
      hashString(seed) % answerPatterns.length
    ];

  const targets = fullPattern.slice(
    0,
    data.questions.length
  );

  const changedQuestions = [];

  data.questions = data.questions.map(
    (question, questionIndex) => {
      const oldOptions = [...question.options];
      const oldAnswer = question.answer;
      const correctText = oldOptions[oldAnswer];
      const targetAnswer = targets[questionIndex];

      const newOptions = new Array(4);
      newOptions[targetAnswer] = correctText;

      let cursor = 0;

      for (
        let oldIndex = 0;
        oldIndex < oldOptions.length;
        oldIndex++
      ) {
        if (oldIndex === oldAnswer) continue;

        while (newOptions[cursor] !== undefined) {
          cursor++;
        }

        newOptions[cursor] = oldOptions[oldIndex];
        cursor++;
      }

      const oldToNew = oldOptions.map(
        (option) => newOptions.indexOf(option)
      );

      if (oldAnswer !== targetAnswer) {
        changedQuestions.push(
          question.id || `Q${questionIndex + 1}`
        );
      }

      return {
        ...question,
        options: newOptions,
        answer: targetAnswer,
        answer_text: correctText,
        explain: remapOptionLetters(
          question.explain,
          oldToNew
        ),
        keyPoint: remapOptionLetters(
          question.keyPoint,
          oldToNew
        )
      };
    }
  );

  data.question_count = data.questions.length;

  const answerLetters = data.questions
    .map(
      (question) =>
        ["A", "B", "C", "D"][question.answer]
    )
    .join(",");

  return {
    normalized_json: JSON.stringify(data, null, 2),
    normalization_status: "NORMALIZED",
    normalization_report:
      `已归一化${data.question_count}道题；` +
      `答案位置为${answerLetters}；` +
      `调整题目：${
        changedQuestions.join(",") || "无"
      }。`
  };
}
